public class ArchiverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Compressor rle = new RunLength();
        check("compress(\"aaab\")", "a3b1", rle.compress("aaab"));
        check("compress(\"abc\")", "a1b1c1", rle.compress("abc"));
        check("compress of one long run", "w5", rle.compress("wwwww"));
        check("compress of the empty string", "", rle.compress(""));
        check("compress(\"aabbaa\") keeps separate runs", "a2b2a2", rle.compress("aabbaa"));
        Archiver archiver = new Archiver(rle);
        check("archive of two inputs", "a3b1|z2", archiver.archive(new String[]{ "aaab", "zz" }));
        check("archive of one input has no separator", "a3b1", archiver.archive(new String[]{ "aaab" }));
        check("archive of an empty array", "", archiver.archive(new String[0]));
        Compressor shouting = new Compressor() {
            public String compress(String input) { return input.toUpperCase(java.util.Locale.US); }
        };
        check("archiver uses whichever strategy is injected", "HI|THERE", new Archiver(shouting).archive(new String[]{ "hi", "there" }));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

